22|type RegisteredModel = {
23|  entry: AiModelEntry;
24|  provider: IAiProvider;
25|};
26|
27|export class AiManager {
28|  private static instance: AiManager;
29|  private models = new Map<string, RegisteredModel>();
30|  private settings: AiSettings | null = null;
31|  private defaultSystemContext = 'You are AppEnd OS Assistant, an elite software architect and AI orchestrator. Provide concise, highly technical responses.';
32|
33|  private constructor() {}
34|
35|  public static getInstance(): AiManager {
36|    if (!AiManager.instance) {
37|      AiManager.instance = new AiManager();
38|    }
39|    return AiManager.instance;
40|  }
