42|  @LogMethod({ id: 'AiManager.reloadFromSettings', minLevel: LogLevel.INFO })
43|  public reloadFromSettings(settings: AiSettings) {
44|    this.settings = settings;
45|    this.models.clear();
46|
47|    settings.models.forEach((entry) => {
48|      if (!entry.enabled) return;
49|
50|      const providerConfig = resolveAiProviderConfig(settings, entry.provider);
51|      if (entry.provider !== 'ollama' && !providerConfig?.apiKey?.trim()) return;
52|
53|      try {
54|        const provider = createProviderForModel(entry, providerConfig);
55|        this.models.set(entry.id, { entry, provider });
56|        logger.info('AiManager', 'Registered AI model', {
57|          modelId: entry.id,
58|          provider: getAiProviderLabel(entry.provider, entry.providerLabel),
59|        });
60|      } catch (error) {
61|        logger.warn('AiManager', 'Skipped AI model registration', {
62|          modelId: entry.id,
63|          error: error instanceof Error ? error.message : String(error),
64|        });
65|      }
66|    });
67|  }
68|
69|  public getSettings(): AiSettings | null {
70|    return this.settings;
71|  }
72|
73|  @LogMethod({ id: 'AiManager.resolveModel' })
74|  public resolveModel(modelId?: string): RegisteredModel {
75|    const settings = this.settings;
76|    if (!settings?.enabled) {
77|      throw new Error('AI is disabled in platform settings.');
78|    }
79|
80|    const resolvedId = modelId?.trim() || settings.defaultModelId;
81|    const registered = this.models.get(resolvedId);
82|    if (!registered) {
83|      throw new Error(`AI model "${resolvedId}" is not configured or enabled.`);
84|    }
85|    return registered;
86|  }
