88|  @LogMethod({ id: 'AiManager.processChat' })
89|  public async processChat(
90|    messages: ChatMessage[],
91|    modelId?: string,
92|    systemContext?: string,
93|  ): Promise<string> {
94|    const { entry, provider } = this.resolveModel(modelId);
95|    if (!isAiModelChatCapable(entry)) {
96|      throw new Error(
97|        `AI model "${entry.name}" (${entry.modelId}) does not support chat. Use a chat-capable model instead.`,
98|      );
99|    }
100|    return provider.chat(messages, systemContext ?? this.defaultSystemContext);
101|  }
102|
103|  public canStreamModel(modelId?: string): boolean {
104|    try {
105|      const { entry, provider } = this.resolveModel(modelId);
106|      return Boolean(entry.capabilities.streaming && typeof provider.streamChat === 'function');
107|    } catch {
108|      return false;
109|    }
110|  }
111|
112|  @LogMethod({ id: 'AiManager.processChatStream' })
113|  public async processChatStream(
114|    messages: ChatMessage[],
115|    modelId: string | undefined,
116|    onDelta: (delta: string) => void,
117|    systemContext?: string,
118|  ): Promise<{ text: string; modelId: string; streamed: boolean }> {
119|    const { entry, provider } = this.resolveModel(modelId);
120|    if (!isAiModelChatCapable(entry)) {
121|      throw new Error(
122|        `AI model "${entry.name}" (${entry.modelId}) does not support chat. Use a chat-capable model instead.`,
123|      );
124|    }
125|
126|    const resolvedContext = systemContext ?? this.defaultSystemContext;
127|    if (entry.capabilities.streaming && typeof provider.streamChat === 'function') {
128|      const text = await provider.streamChat(messages, resolvedContext, onDelta);
129|      return { text, modelId: entry.id, streamed: true };
130|    }
131|
132|    const text = await provider.chat(messages, resolvedContext);
133|    onDelta(text);
134|    return { text, modelId: entry.id, streamed: false };
135|  }
