137|  @LogMethod({ id: 'AiManager.testModel' })
138|  public async testModel(modelId: string): Promise<string> {
139|    const settings = this.settings;
140|    const entry = settings?.models.find((model) => model.id === modelId);
141|    if (!entry || !settings) {
142|      throw new Error(`AI model "${modelId}" was not found.`);
143|    }
144|
145|    const provider = createProviderForSettingsModel(settings, entry);
146|    if (provider.testConnection) {
147|      return provider.testConnection();
148|    }
149|    if (!isAiModelChatCapable(entry)) {
150|      return `Model "${entry.name}" is configured for ${entry.capabilities.imageGeneration ? 'image generation' : 'specialized use'} and does not support chat tests.`;
151|    }
152|    return provider.chat([{ role: 'user', content: 'ping' }]);
153|  }
154|
155|  @LogMethod({ id: 'AiManager.testProvider' })
156|  public async testProvider(providerKind: AiModelEntry['provider']): Promise<string> {
157|    const settings = this.settings;
158|    if (!settings) {
159|      throw new Error('AI settings are not loaded.');
160|    }
161|
162|    const candidate = settings.models.find((model) => model.provider === providerKind);
163|    if (!candidate) {
164|      throw new Error(`No model is configured for provider "${providerKind}".`);
165|    }
166|
167|    return this.testModel(candidate.id);
168|  }
