170|  @LogMethod({ id: 'AiManager.listRemoteModels' })
171|  public async listRemoteModels(providerKind: AiProviderKind): Promise<AiRemoteModelSummary[]> {
172|    const settings = this.settings;
173|    if (!settings) {
174|      throw new Error('AI settings are not loaded.');
175|    }
176|
177|    const providerConfig = resolveAiProviderConfig(settings, providerKind);
178|    if (!providerConfig) {
179|      throw new Error(`Provider "${providerKind}" was not found.`);
180|    }
181|
182|    const probeEntry: AiModelEntry = {
183|      id: `__remote-models-probe-${providerKind}`,
184|      name: 'Remote model probe',
185|      provider: providerKind,
186|      providerLabel: providerConfig.providerLabel,
187|      modelId: 'probe',
188|      enabled: false,
189|      capabilities: { ...DEFAULT_AI_CAPABILITIES },
190|    };
191|
192|    const provider = createProviderForModel(probeEntry, providerConfig);
193|    if (!provider.listRemoteModels) {
194|      throw new Error(`Provider "${providerKind}" does not support listing remote models.`);
195|    }
196|
197|    return provider.listRemoteModels();
198|  }
